# NI! Your Code Requires... a SHRUBBERY of Tests!

*The Knights assemble, rustling ominously*

We are the Knights who say NI! And we DEMAND you bring us... a TEST SUITE! A nice one. And not too expensive.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// NI! The sacred mocks!
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Holy Grail', price: 999.99 },
  { id: '2', name: 'Shrubbery', price: 3.50 },
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 1003.49,
    clearCart: mockClearCart,
  }),
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout - The Knights Demand These Tests!', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // NI! THE HAPPY PATH SHRUBBERY!
  describe('Complete Checkout Flow', () => {
    it('should complete full checkout journey from shipping to confirmation', async () => {
      const user = userEvent.setup();
      mockProcessPayment.mockResolvedValue({ orderId: 'NI-12345' });

      render(<Checkout onComplete={mockOnComplete} onCancel={mockOnCancel} />);

      // Arrange & Act: Shipping
      await user.type(screen.getByLabelText(/street address/i), '42 Shrubbery Lane');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act: Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Sir Robin');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert: Review displays correctly
      expect(screen.getByText(/holy grail/i)).toBeInTheDocument();
      expect(screen.getByText(/\$1003\.49/)).toBeInTheDocument();

      // Act: Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert: Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/NI-12345/)).toBeInTheDocument();
      });
      expect(mockOnComplete).toHaveBeenCalledWith('NI-12345');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  // NI! VALIDATION SHRUBBERY!
  describe('Form Validation', () => {
    it('should display error when street address is empty', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('should validate ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'NI');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('should validate card number is 16 digits', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to payment step first
      await fillShippingForm(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card/i)).toBeInTheDocument();
    });
  });

  // NI! ERROR RECOVERY SHRUBBERY!
  describe('Error States and Recovery', () => {
    it('should display payment error and allow retry', async () => {
      const user = userEvent.setup();
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined! NI!'));
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'RETRY-001' });

      render(<Checkout />);
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });

      // Retry
      await user.click(screen.getByRole('button', { name: /place order/i }));
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
    });
  });

  // NI! LOADING STATE SHRUBBERY!
  describe('Loading States', () => {
    it('should disable buttons and show loading during submission', async () => {
      const user = userEvent.setup();
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));

      render(<Checkout />);
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  // NI! ACCESSIBILITY SHRUBBERY - THE MOST SACRED!
  describe('Accessibility', () => {
    it('should have no axe violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('should announce errors to screen readers', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const alerts = screen.getAllByRole('alert');
      expect(alerts.length).toBeGreaterThan(0);
    });

    it('should indicate current step in progress indicator', () => {
      render(<Checkout />);
      expect(screen.getByText('Shipping').closest('li')).toHaveAttribute('aria-current', 'step');
    });
  });

  // NI! EDGE CASE SHRUBBERY!
  describe('Edge Cases', () => {
    it('should show empty cart message when cart is empty', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });

      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});

// Helper functions - not too expensive!
async function fillShippingForm(user) {
  await user.type(screen.getByLabelText(/street address/i), '42 Shrubbery Lane');
  await user.type(screen.getByLabelText(/city/i), 'Camelot');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '90210');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReviewStep(user) {
  await fillShippingForm(user);
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Sir Robin');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
